SELECT * FROM `user`
WHERE is_deleted = 0 AND id IN
#{uid}

SELECT u.* FROM `user` u WHERE u.is_deleted = 0 AND u.status = 0
AND ( u.username LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') )
AND NOT EXISTS ( SELECT 1 FROM org_member om WHERE om.tenant_id = #{tenantId} AND om.user_id = u.id AND om.is_deleted = 0 AND om.status = 0 ) ORDER BY u.gmt_create DESC, u.id DESC LIMIT #{limit}
